import type { FoodItem } from '../types/health.js';

/**
 * Story 391 — the one `food_items` select list. The food-items, meals and consumption-entries
 * repositories each kept a copy, and the meals copy drifted: a meal ingredient's `food_item`
 * came back without `image_path` and `archived_at` although it is typed `FoodItem`.
 */
const FOOD_ITEM_COLUMN_NAMES = [
    'id', 'canonical_name', 'display_name', 'brand', 'barcode',
    'source', 'source_ref', 'base_amount', 'base_unit', 'default_serving_amount',
    'serving_label', 'serving_quantity',
    'calories_per_base', 'protein_g_per_base', 'carbs_g_per_base', 'fat_g_per_base',
    'fiber_g_per_base', 'sugar_g_per_base', 'sodium_mg_per_base',
    'use_count', 'last_used_at', 'raw_json', 'image_path', 'archived_at', 'created_at', 'updated_at',
] as const satisfies readonly (keyof FoodItem)[];

export const FOOD_ITEM_COLUMNS = FOOD_ITEM_COLUMN_NAMES.join(', ');

/** The same list qualified by a table alias, for a join (`fi.id, fi.canonical_name, …`). */
export function foodItemColumns(alias: string): string {
    return FOOD_ITEM_COLUMN_NAMES.map((column) => `${alias}.${column}`).join(', ');
}
